// Renders the OKLCH token contract (./tokens.ts) to CSS custom properties.
// Pure: no I/O. tools/web/gen-tokens.ts writes the output; tokens-contract.test.ts
// fails when the committed CSS files differ from this output.

import {
  colourRoles,
  elevation,
  fonts,
  lineHeight,
  motion,
  radius,
  sizeScale,
  spacing,
  themes,
} from "./tokens";
import type { ColourRole, ThemeColours } from "./tokens";

export const TOKENS_CSS_HEADER =
  "/* Generated by tools/web/gen-tokens.ts from dashboard/src/design/tokens.ts. Do not edit. */";

function kebab(name: string): string {
  return name.replace(/([a-z])([A-Z0-9])/g, "$1-$2").toLowerCase();
}

export function cssVarName(role: ColourRole): string {
  return `--sw-${kebab(role)}`;
}

function colourDecls(colours: ThemeColours): string[] {
  return colourRoles.map((role) => `  ${cssVarName(role)}: ${colours[role]};`);
}

// Instrument Serif is landing-only (spec 5.3): the dashboard CSS never names it.
export type TokenSurface = "dashboard" | "website";

function sharedDecls(surface: TokenSurface): string[] {
  const decls: string[] = [];
  if (surface === "website") decls.push(`  --sw-font-display: ${fonts.display};`);
  decls.push(`  --sw-font-body: ${fonts.body};`);
  decls.push(`  --sw-font-mono: ${fonts.mono};`);
  for (const [name, size] of Object.entries(sizeScale)) {
    decls.push(`  --sw-size-${kebab(name)}: ${size};`);
  }
  for (const [name, value] of Object.entries(lineHeight)) {
    decls.push(`  --sw-leading-${kebab(name)}: ${value};`);
  }
  for (const [key, px] of Object.entries(spacing)) {
    decls.push(`  --sw-space-${key}: ${px}px;`);
  }
  for (const [name, px] of Object.entries(radius)) {
    decls.push(`  --sw-radius-${name}: ${px}px;`);
  }
  for (const [name, value] of Object.entries(elevation)) {
    decls.push(`  --sw-elev-${name}: ${value};`);
  }
  for (const [name, value] of Object.entries(motion.duration)) {
    decls.push(`  --sw-motion-${name}: ${value};`);
  }
  decls.push(`  --sw-ease-standard: ${motion.easing.standard};`);
  decls.push(`  --sw-ease-emphasized: ${motion.easing.emphasized};`);
  decls.push("  --sw-motion-travel: 1;");
  return decls;
}

function block(selector: string, decls: string[]): string[] {
  return [`${selector} {`, ...decls, "}"];
}

export function renderTokensCss(surface: TokenSurface): string {
  const reducedDecls = [
    `  --sw-motion-fast: ${motion.reduced.duration};`,
    `  --sw-motion-base: ${motion.reduced.duration};`,
    `  --sw-motion-slow: ${motion.reduced.duration};`,
    `  --sw-motion-travel: ${motion.reduced.travel};`,
  ];
  const lines = [
    TOKENS_CSS_HEADER,
    ...block(":root", ["  color-scheme: dark;", ...colourDecls(themes.dark), ...sharedDecls(surface)]),
    "",
    "@media (prefers-color-scheme: light) {",
    ...block(':root:not([data-theme="dark"])', ["  color-scheme: light;", ...colourDecls(themes.light)]).map(
      (line) => `  ${line}`,
    ),
    "}",
    "",
    ...block(':root[data-theme="light"]', ["  color-scheme: light;", ...colourDecls(themes.light)]),
    "",
    "@media (prefers-reduced-motion: reduce) {",
    ...block(":root", reducedDecls).map((line) => `  ${line}`),
    "}",
    "",
  ];
  return lines.join("\n");
}
